const n = $json;
const cfg = $('Config').first().json;
const esc = (t) => String(t ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/\n/g,'<br>');
const dia = (d) => { if (!d) return ''; const p = String(d).slice(0,10).split('-'); return p.length === 3 ? `${p[2]}/${p[1]}` : ''; };
const d = n.dados || {};
const pessoa = n.pessoa || {};
const nome = String(pessoa.nome || '').split(' ')[0] || 'Oi';

const linha = (rotulo, valor) => valor ? `<tr><td style="padding:2px 12px 2px 0;color:#6b7280">${rotulo}</td><td style="padding:2px 0"><b>${esc(valor)}</b></td></tr>` : '';
let corpo = '';

if (n.tipo === 'resumo_diario') {
  const lista = (itens) => (itens || []).map(i =>
    `<li style="margin:0 0 8px 0"><b>${esc(i.titulo)}</b>${i.cliente ? ' (' + esc(i.cliente) + ')' : ''}${i.acao ? '<br><span style="color:#6b7280">' + esc(i.acao) + ' · prazo ' + dia(i.prazo) + '</span>' : '<br><span style="color:#6b7280">prazo ' + dia(i.prazo) + '</span>'}</li>`).join('');
  if ((d.atrasadas || []).length) corpo += `<h3 style="margin:16px 0 8px;color:#b91c1c">Atrasadas (${d.atrasadas.length})</h3><ul style="padding-left:18px;margin:0">${lista(d.atrasadas)}</ul>`;
  if ((d.hoje || []).length) corpo += `<h3 style="margin:16px 0 8px">Para hoje (${d.hoje.length})</h3><ul style="padding-left:18px;margin:0">${lista(d.hoje)}</ul>`;
} else if (n.tipo === 'resumo_equipe') {
  const linhas = (d.pessoas || []).map(x => `<tr><td style="padding:4px 14px 4px 0"><b>${esc(x.nome)}</b></td><td style="padding:4px 14px;color:${x.atrasadas ? '#b91c1c' : '#111827'}">${x.atrasadas} atrasadas</td><td style="padding:4px 14px">${x.hoje} hoje</td><td style="padding:4px 0;color:#6b7280">${x.proximos7} nos próximos 7 dias</td></tr>`).join('');
  corpo = `<p style="margin:0 0 10px"><b>${d.atrasadas}</b> atrasadas e <b>${d.hoje}</b> para hoje na equipe.</p><table style="border-collapse:collapse">${linhas}</table>`;
  if ((d.clientes || []).length) corpo += `<h3 style="margin:16px 0 6px">Clientes com mais atraso</h3><ul style="padding-left:18px;margin:0">${d.clientes.map(c => `<li>${esc(c.cliente)}: ${c.atrasadas}</li>`).join('')}</ul>`;
} else if (n.tipo === 'mencao' || n.tipo === 'comentario') {
  corpo = `<p style="margin:0 0 8px">${esc(d.por || 'Alguém')} ${n.tipo === 'mencao' ? 'mencionou você' : 'comentou'} em <b>${esc(d.titulo)}</b>:</p>` +
          `<blockquote style="margin:8px 0;padding:8px 12px;border-left:3px solid #c9a24d;background:#faf7ef">${esc(d.texto)}</blockquote>`;
} else {
  const intro = {
    atribuida: 'Uma tarefa nova ficou com você.',
    reatribuida: d.quantidade ? `${esc(d.por || 'Alguém')} passou ${d.quantidade} tarefas abertas para você.` : `${esc(d.por || 'Alguém')} passou esta tarefa para você.`,
    na_sua_etapa: 'Uma peça chegou na sua etapa.',
    devolvida: `${esc(d.por || 'Alguém')} devolveu esta peça para você.`,
  }[n.tipo] || '';
  corpo = `<p style="margin:0 0 10px">${intro}</p><table style="border-collapse:collapse">` +
    linha('Tarefa', d.titulo) + linha('Cliente', d.cliente) + linha('Situação', d.estado) +
    linha('Sua ação', d.proxima_acao) + linha('Prazo', dia(d.prazo)) + `</table>`;
  if (n.tipo === 'devolvida' && d.motivo) {
    corpo += `<p style="margin:12px 0 4px"><b>Motivo da devolução</b></p><blockquote style="margin:0;padding:8px 12px;border-left:3px solid #b91c1c;background:#fdf2f2">${esc(d.motivo)}</blockquote>`;
  }
}

const botao = cfg.app_url ? `<p style="margin:20px 0 0"><a href="${esc(cfg.app_url)}" style="background:#0f1b3d;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none">Abrir o sistema</a></p>` : '';
const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#111827;max-width:560px">` +
  `<p style="margin:0 0 12px">Oi, ${esc(nome)}.</p>${corpo}${botao}` +
  `<p style="margin:24px 0 0;color:#9ca3af;font-size:12px">Aviso automático do sistema de tarefas da EuforIA. Você liga ou desliga estes avisos no seu perfil.</p></div>`;

return { json: { notif_id: n.id, tentativas: n.tentativas || 0, to: pessoa.email || '', subject: n.assunto, html } };
